// Mock 效能指標資料
const hostData = {
  'prod-node-03': { cpu: 94, memory: 78, network_in: 1200, network_out: 340, disk_io: 45, status: 'warning' },
  'prod-node-01': { cpu: 23, memory: 45, network_in: 800, network_out: 200, disk_io: 12, status: 'normal' },
  'prod-db-01': { cpu: 67, memory: 88, network_in: 450, network_out: 120, disk_io: 92, status: 'critical' },
};

const host = query.host_name || 'prod-node-03';
const data = hostData[host] || { cpu: 50, memory: 50, status: 'unknown' };

return JSON.stringify({
  host,
  timestamp: new Date().toISOString(),
  metrics: data,
  alert: data.cpu > 90 ? 'CPU CRITICAL: 超過 90%' : data.cpu > 80 ? 'CPU WARNING: 超過 80%' : 'CPU 正常'
});

// Mock Log 搜尋結果
const logs = [
  { time: '10:23:41', level: 'ERROR', msg: 'OOM Killer activated: process api-server (pid 34521) killed', host: 'prod-node-03' },
  { time: '10:23:38', level: 'WARN',  msg: 'Memory pressure: 94% used, swap usage 100%', host: 'prod-node-03' },
  { time: '10:23:35', level: 'ERROR', msg: 'Cannot allocate memory for new thread in api-server', host: 'prod-node-03' },
  { time: '10:22:10', level: 'INFO',  msg: 'Deployment of api-server v2.3.1 completed', host: 'prod-node-03' },
  { time: '10:20:00', level: 'INFO',  msg: 'CPU throttling disabled for cpu.cfs_quota_us=-1', host: 'prod-node-03' },
];

const kw = (query.keyword || '').toLowerCase();
const host = query.host || 'prod-node-03';

const filtered = logs.filter(l =>
  (l.host === host) && (kw === '' || l.msg.toLowerCase().includes(kw) || l.level.toLowerCase().includes(kw))
);

return JSON.stringify({ total: filtered.length, logs: filtered, suggestion: '最近有部署 api-server v2.3.1，可能是 Memory leak 導致 OOM' });

// Mock Runbook 知識庫
const runbooks = {
  'OOM': {
    title: 'OOM (Out of Memory) 處理 SOP',
    severity: 'P1',
    steps: ['1. 確認哪個 process 被 OOM Killer 終止', '2. 執行 kubectl rollout restart 重啟 pod', '3. 調高 Memory Limit 至 2x 當前值', '4. 部署後監控 30 分鐘', '5. 若再發生，開 Jira Epic 進行 memory profiling'],
    auto_fix: 'kubectl rollout restart deployment/api-server -n production',
    escalate_if: '重啟後 15 分鐘內再次 OOM'
  },
  'CPU_high': {
    title: 'CPU 過高處理 SOP',
    severity: 'P2',
    steps: ['1. 用 top/htop 找出高 CPU process', '2. 查看最近 30 分鐘 deployment 記錄', '3. 若有新部署，評估是否 rollback', '4. 設定 HPA（Horizontal Pod Autoscaler）'],
    auto_fix: 'kubectl top pods -n production --sort-by=cpu',
    escalate_if: 'CPU > 90% 持續超過 15 分鐘'
  },
};

const issue = query.issue_type || 'OOM';
const rb = runbooks[issue] || runbooks['CPU_high'];

return JSON.stringify({ issue_type: issue, runbook: rb, last_updated: '2026-05-15' });

// Mock Jira Incident 建立
const ticketId = 'ITOPS-' + Math.floor(Math.random() * 9000 + 1000);
const ticket = {
  id: ticketId,
  status: 'created',
  title: query.title || 'AI 自動偵測 Incident',
  severity: query.severity || 'P2',
  host: query.host || 'unknown',
  description: query.description || '由 AI Agent 自動建立',
  assignee: 'oncall-engineer',
  created_at: new Date().toISOString(),
  jira_url: 'https://tsmc-it.atlassian.net/browse/' + ticketId,
  pagerduty: severity === 'P1' ? 'PagerDuty 已通知 On-call 工程師' : '一般通知已發送'
};

return JSON.stringify({ success: true, ticket });
